"""Vetted Python analysis scaffolds. Each template is plain Python (pandas/numpy only) that:
verifies the export's SHA-256 and row count before doing anything, reads text/ID columns
losslessly, computes with documented methods, and runs a self-check at the end that fails loudly
if its own numbers do not reconcile. Generated scripts embed data ONLY via repr() of validated
primitives, never by string-splicing user text into code."""

HEADER = r'''#!/usr/bin/env python3
# {title}
# Generated by Medkart Data Connector. Template: {template}
# Requires: pip install pandas numpy
# Run:      python {script_name}            (downloads the export, verifies it, analyses it)
#           python {script_name} --file {filename}   (use a local copy)
import argparse
import hashlib
import sys
import urllib.request
from decimal import Decimal
from pathlib import Path

import numpy as np
import pandas as pd

EXPECTED = {expected!r}      # export manifest: filename, rows, sha256, columns, kinds
SOURCE_SQL = {sql!r}
DOWNLOAD_URL = {url!r}       # short-lived; ask your AI assistant for a new link if it has expired
COLS = {cols!r}              # role -> column name in the export
PARAMS = {params!r}
OUT = Path("output")


def load_export(path_arg=None):
    path = Path(path_arg or EXPECTED["filename"])
    if not path.exists():
        try:
            print("Downloading export ...")
            urllib.request.urlretrieve(DOWNLOAD_URL, path)
        except Exception as e:
            sys.exit(f"Could not download the export ({{e}}). Links expire after about 30 "
                     "minutes: ask your AI assistant for a new link (get_export_link), or pass --file PATH.")
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    if digest != EXPECTED["sha256"]:
        sys.exit("CHECKSUM MISMATCH: the file is incomplete or was modified. Do not trust any "
                 "result from it; download it again.")
    # Read everything as text first so codes like 00123 are never altered, then convert by kind.
    raw = pd.read_csv(path, dtype=str, keep_default_na=False)
    if list(raw.columns) != [c["name"] for c in EXPECTED["columns"]]:
        sys.exit("Column mismatch between the file and its manifest.")
    if len(raw) != EXPECTED["rows"]:
        sys.exit(f"ROW COUNT MISMATCH: file has {{len(raw)}} rows, export has {{EXPECTED['rows']}}.")
    df = pd.DataFrame(index=raw.index)
    for name, kind in EXPECTED["kinds"].items():
        s = raw[name]
        blank = s == ""
        if kind == "int":
            df[name] = pd.to_numeric(s.mask(blank), errors="raise").astype("Int64")
        elif kind in ("float", "decimal"):
            df[name] = pd.to_numeric(s.mask(blank), errors="raise").astype("float64")
            if kind == "decimal":   # exact total from the text, shown so float rounding is visible
                exact = sum((Decimal(v) for v in s[~blank]), Decimal(0))
                print(f"  [{{name}}] exact total = {{exact}}")
        elif kind == "date":
            df[name] = pd.to_datetime(s.mask(blank), format="ISO8601", utc=True).dt.tz_convert(None)
        elif kind == "bool":
            df[name] = s.map({{"true": True, "false": False}}).astype("boolean")
        else:
            df[name] = s.mask(blank)          # text; empty cell = NULL
    print(f"Loaded {{len(df):,}} rows, checksum OK ({{digest[:12]}}...)")
    return df


def to_dates(df, role):
    """Return the role's column as datetimes (parses ISO text dates; fails loudly on junk)."""
    s = df[COLS[role]]
    if pd.api.types.is_datetime64_any_dtype(s):
        return s
    return pd.to_datetime(s, format="ISO8601", errors="raise")


def check(cond, message):
    if not cond:
        sys.exit(f"SELF-CHECK FAILED: {{message}}")


'''

