ABC_XYZ = r'''
def analyze(df):
    # ABC = share of total value (or quantity); XYZ = demand variability (coefficient of
    # variation of monthly quantity, zero months included).
    a_cut, b_cut = PARAMS["abc_a_pct"], PARAMS["abc_b_pct"]
    x_cut, y_cut = PARAMS["xyz_x_cv"], PARAMS["xyz_y_cv"]
    d = pd.DataFrame({
        "item": df[COLS["item"]],
        "date": to_dates(df, "date"),
        "qty": df[COLS["quantity"]].astype("float64"),
        "val": df[COLS.get("value") or COLS["quantity"]].astype("float64"),
    })
    n0 = len(d)
    d = d.dropna(subset=["item", "date", "qty", "val"])
    if len(d) < n0:
        print(f"Note: ignored {n0 - len(d):,} rows with a missing item/date/quantity/value.")
    d["period"] = d["date"].dt.to_period("M")

    total = d.groupby("item")["val"].sum().sort_values(ascending=False)
    check(total.sum() > 0, "total value is not positive; ABC shares are undefined")
    share = total / total.sum()
    before = share.cumsum() - share              # cumulative share BEFORE the item
    abc = np.where(before < a_cut / 100, "A", np.where(before < b_cut / 100, "B", "C"))

    months = pd.period_range(d["period"].min(), d["period"].max(), freq="M")
    m = (d.groupby(["item", "period"])["qty"].sum().unstack(fill_value=0)
         .reindex(columns=months, fill_value=0))
    mean, std = m.mean(axis=1), m.std(axis=1, ddof=0)
    cv = (std / mean.where(mean > 0)).reindex(total.index)
    xyz = np.where(cv <= x_cut, "X", np.where(cv <= y_cut, "Y", "Z"))   # NaN cv (no demand) -> Z
    if len(months) < 6:
        print(f"WARNING: only {len(months)} months of history; XYZ classes are unreliable.")

    res = pd.DataFrame({"item": total.index, "total_value": total.values,
                        "share_pct": (share.values * 100).round(3),
                        "cum_share_pct": (share.cumsum().values * 100).round(3),
                        "abc": abc, "monthly_mean_qty": mean.reindex(total.index).values,
                        "cv": cv.values, "xyz": xyz})
    res["class"] = res["abc"] + res["xyz"]
    matrix = pd.crosstab(res["abc"], res["xyz"])

    check(abs(share.sum() - 1) < 1e-9, "ABC shares do not add to 100%")
    check(len(res) == d["item"].nunique(), "item count mismatch")
    check(int(matrix.to_numpy().sum()) == len(res), "matrix does not cover every item")
    res.to_csv(OUT / "abc_xyz_items.csv", index=False)
    matrix.to_csv(OUT / "abc_xyz_matrix.csv")
    print(f"\n{len(res):,} items over {len(months)} months. ABC x XYZ matrix (item counts):")
    print(matrix)
    print("\nTop 10 items:")
    print(res.head(10).to_string(index=False))
    print(f"\nWrote {OUT / 'abc_xyz_items.csv'} and {OUT / 'abc_xyz_matrix.csv'}")
    return res
'''

RFM = r'''
def analyze(df):
    # Recency (days since last order), Frequency (orders), Monetary (total value), each scored
    # 1-5 by rank quintile (5 = best).
    d = pd.DataFrame({"cust": df[COLS["customer"]], "date": to_dates(df, "date"),
                      "val": df[COLS["value"]].astype("float64")})
    if COLS.get("order_id"):
        d["order"] = df[COLS["order_id"]]
    n0 = len(d)
    d = d.dropna(subset=["cust", "date", "val"])
    if len(d) < n0:
        print(f"Note: ignored {n0 - len(d):,} rows with a missing customer/date/value.")
    snap = pd.Timestamp(PARAMS["snapshot_date"]) if PARAMS["snapshot_date"] \
        else d["date"].max().normalize() + pd.Timedelta(days=1)
    d = d[d["date"] < snap]
    g = d.groupby("cust")
    freq = g["order"].nunique() if "order" in d else g.size()
    rfm = pd.DataFrame({"recency_days": (snap - g["date"].max()).dt.days,
                        "frequency": freq, "monetary": g["val"].sum()})
    check(len(rfm) >= 5, "need at least 5 customers to score quintiles")

    def quintile(s, higher_is_better):
        r = s.rank(method="first", ascending=higher_is_better)
        return pd.qcut(r, 5, labels=False).astype(int) + 1

    rfm["R"] = quintile(rfm["recency_days"], higher_is_better=False)
    rfm["F"] = quintile(rfm["frequency"], higher_is_better=True)
    rfm["M"] = quintile(rfm["monetary"], higher_is_better=True)

    def segment(r):
        if r.R >= 4 and r.F >= 4:
            return "Champions"
        if r.R >= 3 and r.F >= 3:
            return "Loyal"
        if r.R >= 4:
            return "New / recent"
        if r.R <= 2 and r.F >= 4:
            return "At risk (was frequent)"
        if r.R <= 2:
            return "Lost / hibernating"
        return "Needs attention"

    rfm["segment"] = rfm.apply(segment, axis=1)
    check(len(rfm) == d["cust"].nunique(), "customer count mismatch")
    check(abs(rfm["monetary"].sum() - d["val"].sum()) <= 1e-6 * max(1.0, abs(d["val"].sum())),
          "monetary total does not match the data")
    out = rfm.reset_index().rename(columns={"cust": "customer"})
    out.to_csv(OUT / "rfm_customers.csv", index=False)
    seg = (out.groupby("segment").agg(customers=("customer", "count"),
                                      monetary=("monetary", "sum"),
                                      avg_recency_days=("recency_days", "mean"))
           .sort_values("monetary", ascending=False))
    seg["monetary_share_pct"] = (seg["monetary"] / seg["monetary"].sum() * 100).round(2)
    seg.to_csv(OUT / "rfm_segments.csv")
    print(f"Snapshot date: {snap.date()}  customers: {len(out):,}")
    print(seg.to_string())
    print(f"\nWrote {OUT / 'rfm_customers.csv'} and {OUT / 'rfm_segments.csv'}")
    return out
'''

COHORT = r'''
def analyze(df):
    # Cohort = month of a customer's first activity; retention = share of the cohort active N
    # months later. Cells beyond the data's last month are blank (NOT zero).
    d = pd.DataFrame({"cust": df[COLS["customer"]], "date": to_dates(df, "date")})
    n0 = len(d)
    d = d.dropna()
    if len(d) < n0:
        print(f"Note: ignored {n0 - len(d):,} rows with a missing customer/date.")
    d["pi"] = d["date"].dt.year * 12 + d["date"].dt.month - 1
    first = d.groupby("cust")["pi"].transform("min")
    d["age"] = d["pi"] - first
    d["cohort"] = first
    table = d.groupby(["cohort", "age"])["cust"].nunique().unstack(fill_value=0)
    table = table.reindex(columns=range(int(table.columns.max()) + 1), fill_value=0)
    last = int(d["pi"].max())
    for c in table.index:                         # future months are unknown, not zero
        table.loc[c, [a for a in table.columns if c + a > last]] = np.nan
    size = table[0]
    retention = table.div(size, axis=0) * 100
    label = lambda i: f"{int(i) // 12}-{int(i) % 12 + 1:02d}"
    retention.index = [label(i) for i in retention.index]
    table.index = retention.index
    check(int(size.sum()) == d["cust"].nunique(), "cohort sizes do not add up to unique customers")
    retention.round(1).to_csv(OUT / "cohort_retention_pct.csv")
    table.to_csv(OUT / "cohort_counts.csv")
    print(f"{d['cust'].nunique():,} customers in {len(table)} monthly cohorts "
          f"(data through {label(last)}).")
    print("The most recent month may be partial, which understates its retention.\n")
    print(retention.round(1).to_string())
    print(f"\nWrote {OUT / 'cohort_retention_pct.csv'} and {OUT / 'cohort_counts.csv'}")
    return retention
'''

FORECAST = r'''
def _seasonal_naive(train, h, m):
    return np.array([train[-m + (i % m)] for i in range(h)], dtype=float)


def _moving_avg(train, h, k=4):
    return np.full(h, float(np.mean(train[-k:])))


def _ses(train, h):
    best = None
    for a in np.arange(0.1, 1.0, 0.1):
        level, sse = train[0], 0.0
        for y in train[1:]:
            sse += (y - level) ** 2
            level = a * y + (1 - a) * level
        if best is None or sse < best[0]:
            best = (sse, level)
    return np.full(h, float(best[1]))


def _wape(actual, fc):
    den = float(np.abs(actual).sum())
    return float(np.abs(actual - fc).sum() / den) if den else float("nan")


def _forecast_series(y, h, m):
    methods = {"moving_average_4": lambda t, n: _moving_avg(t, n),
               "simple_exp_smoothing": lambda t, n: _ses(t, n)}
    if len(y) >= 2 * m:
        methods["seasonal_naive"] = lambda t, n: _seasonal_naive(t, n, m)
    hold = max(1, min(h, len(y) // 4))
    train, test = y[:-hold], y[-hold:]
    scores = {name: _wape(test, f(train, hold)) for name, f in methods.items()}
    ok = {k: v for k, v in scores.items() if v == v}
    best = min(ok, key=ok.get) if ok else "moving_average_4"
    fc = np.clip(methods[best](y, h), 0, None)
    return best, scores, fc


def analyze(df):
    # Baseline demand forecast. Backtests three simple methods on a holdout and uses the one with
    # the lowest WAPE. This is a baseline, not a substitute for domain knowledge (promotions,
    # stock-outs and price changes are not modelled).
    freq, h = PARAMS["freq"], PARAMS["horizon"]
    m = 52 if freq == "W" else 12
    d = pd.DataFrame({"date": to_dates(df, "date"),
                      "qty": df[COLS["quantity"]].astype("float64")})
    if COLS.get("item"):
        d["item"] = df[COLS["item"]]
    d = d.dropna(subset=["date", "qty"])
    d["period"] = d["date"].dt.to_period("W" if freq == "W" else "M")
    last_end = d["period"].max().end_time
    if PARAMS["drop_incomplete"] and d["date"].max().normalize() < last_end.normalize():
        print(f"Note: latest {freq} period ({d['period'].max()}) is incomplete and was dropped.")
        d = d[d["period"] < d["period"].max()]
    check(len(d) > 0, "no complete periods of data")
    groups = [("TOTAL", d)]
    if "item" in d:
        top = d.groupby("item")["qty"].sum().nlargest(PARAMS["top_items"]).index
        groups += [(str(i), d[d["item"] == i]) for i in top]
    rows, metrics = [], []
    for name, g in groups:
        idx = pd.period_range(g["period"].min(), g["period"].max(), freq=g["period"].dt.freq)
        y = g.groupby("period")["qty"].sum().reindex(idx, fill_value=0).to_numpy(dtype=float)
        if len(y) < 6:
            print(f"Skipping {name}: only {len(y)} periods of history.")
            continue
        best, scores, fc = _forecast_series(y, h, m)
        check(len(fc) == h and np.all(fc >= 0), f"invalid forecast for {name}")
        metrics.append({"series": name, "periods_of_history": len(y), "method": best,
                        **{f"wape_{k}": round(v, 4) for k, v in scores.items()}})
        for i, v in enumerate(fc, 1):
            rows.append({"series": name, "period": str(idx[-1] + i), "forecast": round(float(v), 3)})
    check(rows, "no series had enough history to forecast")
    pd.DataFrame(rows).to_csv(OUT / "forecast.csv", index=False)
    pd.DataFrame(metrics).to_csv(OUT / "forecast_backtest.csv", index=False)
    print(pd.DataFrame(metrics).to_string(index=False))
    print(f"\nWrote {OUT / 'forecast.csv'} and {OUT / 'forecast_backtest.csv'}")
    return pd.DataFrame(rows)
'''

PVM = r'''
def analyze(df):
    # Price-Volume-Mix bridge of revenue between two periods (half-open: start inclusive, end
    # exclusive). price + volume + mix reconciles EXACTLY to the revenue change.
    dt = to_dates(df, "date")
    d = pd.DataFrame({"item": df[COLS["item"]], "date": dt,
                      "qty": df[COLS["quantity"]].astype("float64"),
                      "rev": df[COLS["revenue"]].astype("float64")}).dropna()
    b = d[(d["date"] >= PARAMS["baseline_start"]) & (d["date"] < PARAMS["baseline_end"])]
    c = d[(d["date"] >= PARAMS["current_start"]) & (d["date"] < PARAMS["current_end"])]
    check(len(b) > 0 and len(c) > 0, "one of the periods has no rows")
    a0 = b.groupby("item").agg(q0=("qty", "sum"), r0=("rev", "sum"))
    a1 = c.groupby("item").agg(q1=("qty", "sum"), r1=("rev", "sum"))
    t = a0.join(a1, how="outer").fillna(0.0)
    t["p0"] = np.where(t.q0 != 0, t.r0 / t.q0.replace(0, np.nan), np.nan)
    t["p1"] = np.where(t.q1 != 0, t.r1 / t.q1.replace(0, np.nan), np.nan)
    t["p0"] = t["p0"].fillna(t["p1"])             # new item: no baseline price -> no price effect
    t["p1"] = t["p1"].fillna(t["p0"])             # lost item: no current price
    t["price_effect"] = (t.p1 - t.p0) * t.q1
    t["vol_mix"] = (t.q1 - t.q0) * t.p0
    Q0, Q1, R0, R1 = t.q0.sum(), t.q1.sum(), t.r0.sum(), t.r1.sum()
    check(Q0 > 0, "baseline volume is zero")
    volume = (Q1 - Q0) * (R0 / Q0)
    mix = t.vol_mix.sum() - volume
    price = t.price_effect.sum()
    bridge = pd.DataFrame({"effect": ["Baseline revenue", "Volume", "Mix", "Price",
                                      "Current revenue"],
                           "amount": [R0, volume, mix, price, R1]})
    check(abs((R0 + volume + mix + price) - R1) <= 1e-6 * max(1.0, abs(R1)),
          "bridge does not reconcile to the revenue change")
    t["total_change"] = t.r1 - t.r0
    t.sort_values("total_change", key=abs, ascending=False).round(4).to_csv(
        OUT / "pvm_by_item.csv")
    bridge.to_csv(OUT / "pvm_bridge.csv", index=False)
    print(bridge.round(2).to_string(index=False))
    print(f"\nRevenue change {R1 - R0:,.2f} = volume {volume:,.2f} + mix {mix:,.2f} "
          f"+ price {price:,.2f}")
    print(f"Wrote {OUT / 'pvm_bridge.csv'} and {OUT / 'pvm_by_item.csv'}")
    return bridge
'''

